using System;using System.IO;using System.Linq;using UnityEditor;using UnityEngine;using TutorialFramework;using UnityEngine.Splines;
[InitializeOnLoad]public static class BatchNextFreeGeometry{
 [Serializable]public class End{public string id;public Vector3 center;public Vector3[] mouths;}
 [Serializable]public class Def{public string id,name,a,b;public bool runtime,reverse;}
 [Serializable]public class Data{public End[] ends;public Def[] definitions;}
 static string Id(UnityEngine.Object o)=>o?GlobalObjectId.GetGlobalObjectIdSlow(o).ToString():"";
 static Vector3 Mouth(GameObject p){var m=p.GetComponentInChildren<MeshFilter>(true);var b=m.sharedMesh.bounds;return m.transform.TransformPoint(new Vector3(b.center.x,0,b.min.z+.025f));}
 static BatchNextFreeGeometry(){EditorApplication.update+=Tick;}
 static void Tick(){if(!File.Exists("Temp/batch-next-free-geometry.flag")||EditorApplication.isCompiling||EditorApplication.isUpdating||Application.isPlaying)return;File.Delete("Temp/batch-next-free-geometry.flag");try{Run();}catch(Exception e){File.WriteAllText("Temp/V12BatchNext/free-geometry-error.txt",e.ToString());}}
 static void Run(){var scene=UnityEngine.SceneManagement.SceneManager.GetActiveScene();var wind=scene.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<FreeLabWindController>(true)).Single();var ends=wind.sockets.Select(s=>{var first=s.plugs[0];var m=first.GetComponentInChildren<MeshFilter>(true);var mouths=s.plugs.Select((p,i)=>{if(i==0)return Mouth(p);float len=m.transform.TransformVector(Vector3.forward*m.sharedMesh.bounds.size.z).magnitude;var pos=p.transform.position;if(Vector3.Distance(pos,first.transform.position)<len*.5f)pos=first.transform.position+m.transform.TransformDirection(Vector3.back).normalized*(len*.8f*i);return Mouth(first)+pos-first.transform.position;}).ToArray();return new End{id=Id(s.endpoint),center=s.endpoint.transform.position,mouths=mouths};}).ToArray();
 var defs=wind.definitions.Select(d=>{var c=d.wireParentTemplate.GetComponentInChildren<SplineContainer>(true);var w=c.GetComponentInParent<FreeLabWire>(true);var so=w?new SerializedObject(w):null;var a=ends.Single(e=>e.id==Id(d.endpointA)).mouths[0];var b=ends.Single(e=>e.id==Id(d.endpointB)).mouths[0];var start=c.transform.TransformPoint((Vector3)c.Spline[0].Position);var end=c.transform.TransformPoint((Vector3)c.Spline[c.Spline.Count-1].Position);return new Def{id=Id(c),name=d.name,a=Id(d.endpointA),b=Id(d.endpointB),runtime=so!=null&&so.FindProperty("fitToAllocatedPlugs").boolValue,reverse=(start-a).sqrMagnitude+(end-b).sqrMagnitude>(start-b).sqrMagnitude+(end-a).sqrMagnitude};}).ToArray();File.WriteAllText("Temp/V12BatchNext/free-definitions.json",JsonUtility.ToJson(new Data{ends=ends,definitions=defs},true));}
}

